#!/bin/sh
# TLS entrypoint wrapper for the postgres, mysql, mariadb and mongodb fixtures (TEST-ONLY PKI).
#
# The test CA / server certificate / server key are bind-mounted read-only from the host
# (target/fixtures/tls, generated by scripts/fixtures-certs.sh) at /oxbase-tls-src. Host files
# keep the host user's owner and mode 0600, which the database user cannot read, and PostgreSQL
# refuses a key that is group/world readable. So this wrapper runs as root before the image's
# own entrypoint, copies the files into the container filesystem with the owner and modes each
# server expects, then hands over to the image entrypoint unchanged.
#
# Env:
#   OXBASE_TLS_OWNER  user:group that must own the copies (postgres:postgres, mysql:mysql)
#   OXBASE_TLS_DIR    destination directory (default /etc/oxbase-tls)
#   OXBASE_TLS_EXTRA  space-separated files from /oxbase-tls-init to copy too (e.g. pg_hba.conf)
#   OXBASE_TLS_COMBINED  optional file name: the server certificate followed by its key in one
#                     PEM (mongod's --tlsCertificateKeyFile), mode 0600 like the key
set -eu

src=/oxbase-tls-src
dest="${OXBASE_TLS_DIR:-/etc/oxbase-tls}"
owner="${OXBASE_TLS_OWNER:?OXBASE_TLS_OWNER must be set (user:group)}"

for f in ca.pem server.pem server-key.pem; do
    if [ ! -s "$src/$f" ]; then
        echo "oxbase-tls: missing $src/$f - run scripts/fixtures-certs.sh (fixtures-up.sh does)" >&2
        exit 1
    fi
done

mkdir -p "$dest"
cp "$src/ca.pem" "$src/server.pem" "$src/server-key.pem" "$dest/"
for f in ${OXBASE_TLS_EXTRA:-}; do
    cp "/oxbase-tls-init/$f" "$dest/"
done
if [ -n "${OXBASE_TLS_COMBINED:-}" ]; then
    cat "$src/server.pem" "$src/server-key.pem" > "$dest/$OXBASE_TLS_COMBINED"
fi
chown -R "$owner" "$dest"
chmod 0750 "$dest"
chmod 0644 "$dest"/*
chmod 0600 "$dest/server-key.pem"
if [ -n "${OXBASE_TLS_COMBINED:-}" ]; then
    chmod 0600 "$dest/$OXBASE_TLS_COMBINED"
fi

exec docker-entrypoint.sh "$@"
